Method.Implementation:
#dim tSC As %Status = $$$OK


 set cfgFileType = "CONFIG" 
 set clsFileType = "CLS"

 Set tProductionClassIncluded = 0
 set $NAMESPACE = nmSp
 Write !, "NAMESPACE: " _ $NAMESPACE 
 set tProductionName = ##class(Ens.Director).GetActiveProductionName()

 if tProductionName = ""
 {
  Write !, "Could not get active production in " _ $NAMESPACE
  Quit $$$ERROR($$$GeneralError, "Could not get active production in " _ $NAMESPACE)
 }
 write !, "Active PROD: " _ tProductionName


 if ((fileType = "*") || (fileType = cfgFileType))
 {
	Set fileName = ..DeployDirectory_"Deployment_" _ cfgFileType _ "_" _compNm_".xml"

 	set tSC = ..CheckoutFile(fileName, passwd, rev )

 	if $$$ISERR(tSC)
 	{
	 	Quit tSC
 	}
	set tSC = ..DeployComponent(compNm, fileName, rev, nmSp, tProductionName, passwd, env)
	if $$$ISERR(tSC)
	{
		Quit tSC
	}
 }
 if ((fileType = "*") || (fileType = clsFileType))
 {
	Set fileName = ..DeployDirectory_"Deployment_" _ clsFileType _ "_" _compNm_".xml"

 	set tSC = ..CheckoutFile(fileName, passwd, rev )

 	if $$$ISERR(tSC)
 	{
	 	Quit tSC
 	}
	set tSC = ..DeployClassFiles(compNm, fileName, rev, nmSp, tProductionName, passwd, env)
 }
 Quit tSC

#dim tSC As %Status = $$$OK
 if (compNm '[ "||") 
 {
  set ItemByConfigName = tProductionName_"||"_compNm
 }
 else
 {
	 set ItemByConfigName = compNm
 }

 Set tItem = ##class(Ens.Config.Production).OpenItemByConfigName(ItemByConfigName)
 If $IsObject(tItem)
 {
		Quit $$$ERROR($$$GeneralError, tItem _ " already exists")
 }

 set parseFl = ##class(ITFCOMMON.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(fileName, compNm)



 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) && (parseFl.IsConfigFile()) )
  {
	 if (parseFl.itemsInfo.GetAt(1).itemName = compNm)
	 {
 		set tSC = ..Deploy(compNm, fileName, "Config", tProductionName)
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		set tSC = ..updateComponentImpl(compNm, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env)
	 		return tSC
 		}
	 }
	 else
	 {
		 Write !, "File does not have config for " _ compNm
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Write !, "Parsing the file failed " _ tSC
  	 Quit tSC
  }
  return tSC

#dim tSC As %Status = $$$OK
 set parseFl = ##class(ITFCOMMON.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(fileName, compNm)

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) )
  {

	 if (parseFl.itemsInfo.Count() < 2)
	 {
		  Write !, "File does not have config for any class in file" _ compNm
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for any class in file " _ compNm)
	 }

	 if (parseFl.itemsInfo.GetAt(1).itemName = compNm)
	 {
 		set tSC = ..Deploy(compNm, fileName, "Class", tProductionName)
 		if $$$ISOK(tSC)
 		{
	 		// Update Database
	 		set tSC = ..updateComponentImpl(compNm, fileName, rev, parseFl.itemsInfo.GetAt(1).itemInfo, env)

	 		// Update Database for each class
	 		FOR ind=2:1:parseFl.itemsInfo.Count()
	 		{
	 		  set tSC = ..updateClassItem(parseFl.itemsInfo.GetAt(ind).itemName, compNm, fileName, 
	 		   parseFl.itemsInfo.GetAt(ind).versionNum, parseFl.itemsInfo.GetAt(ind).itemInfo, env)
	 		   if $$$ISERR(tSC)
	 		   {
		 		   Return tSC
	 		   }
	 		}
 		}
	 }
	 else
	 {
		 Write !, "File does not have config for " _ compNm
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ compNm)
	 }
  }
  else
  {
	 Write !, "Parsing the file failed "
  	 Quit $$$ERROR($$$GeneralError, "Parsing the file failed ")
  }
  Quit tSC

 NEW $NAMESPACE
 set $NAMESPACE = "ITFCOMMON"
 Write !, $NAMESPACE, DeploymentFile, " : " _ fileVersion, " : " _fileInfo
   &sql(Select ID INTO :compId  from ITFCOMMON_SrcCtrl.Component where ComponentName = :componentNm)
   IF (SQLCODE = 0) {
      &sql(Select ID INTO :envId from ITFCOMMON_SrcCtrl.Environment where Name = :env)
      IF (SQLCODE = 0) {
	      set dt = $ZDATETIME($ZTIMESTAMP,3, 1)

         &sql(INSERT INTO ITFCOMMON_SrcCtrl.ComponentImpl
	        (ComponentName, Environment, ImplFile, ImplFileVersion, ImplFileInformation, ImplementionDate )
	         values (:compId, :envId, :DeploymentFile, :fileVersion, :fileInfo, :dt ) )
 	 	 if SQLCODE = 0
 	 	 {
	 	 	 return $$$OK
 	 	 }
 	 	 else
 	 	 {
	 	 	 return $$$ERROR($$$GeneralError, "Insert to ComponentImpl failed " _ $SYSTEM.SQL.SQLCODE(SQLCODE))
 	 	 }
      }
      else
 	 	 {
	 	 	 return $$$ERROR($$$GeneralError, "Select from Environment failed " _ env _ ", " _ $SYSTEM.SQL.SQLCODE(SQLCODE))
 	 	 }
   }
   else
   {
 	 return $$$ERROR($$$GeneralError, "Select from Component failed " _ componentNm _ ", " _ $SYSTEM.SQL.SQLCODE(SQLCODE))
   }

	NEW $NAMESPACE
	set $NAMESPACE = "ITFCOMMON"
	 &sql(Select ID INTO :compId  from ITFCOMMON_SrcCtrl.Component where ComponentName = :componentNm)
   IF (SQLCODE = 0) {
      &sql(Select ID INTO :envId from ITFCOMMON_SrcCtrl.Environment where Name = :env)
      IF (SQLCODE = 0) {
	       set dt = $ZDATETIME($ZTIMESTAMP,3, 1)
	       Write !, clNm _ ": " _ compId_ ": " _envId_ ": " _DeploymentFile_ ": " _fileVersion_ ": " _fileInfo
    		&sql(INSERT INTO ITFCOMMON_SrcCtrl.ClassItem 
 			 (ClassName, ComponentName, Environment, ClassExportFile, ClassExportFileVersion, ClassExportFileInformation, ImportDate
  			   )
 	         values (:clNm, :compId, :envId, :DeploymentFile, :fileVersion, :fileInfo, :dt ) )
 	 	 if SQLCODE = 0
 	 	 {
	 	 	 return $$$OK
 	 	 }
 	 	 else
 	 	 {
	 	 	 return $$$ERROR($$$GeneralError, "Insert to ComponentImpl failed " _ $SYSTEM.SQL.SQLCODE(SQLCODE))
 	 	 }
      }
      else
 	 	 {
	 	 	 return $$$ERROR($$$GeneralError, "Select from Environment failed " _ $SYSTEM.SQL.SQLCODE(SQLCODE))
 	 	 }
   }
   else
   {
 	 return $$$ERROR($$$GeneralError, "Select from Component failed " _ componentNm _ " " _ $SYSTEM.SQL.SQLCODE(SQLCODE))
   }

  #dim tSC As %Status
  #dim clsList As  %ListOfDataTypes
  set tSC = $$$OK

  set clsList = ##class(%ListOfDataTypes).%New()
  Do clsList.Insert(tItemName)
  set tSC = ..GetClassesForComponent(tItemName, clsList)
  if $$$ISERR(tSC)
  {
	  Quit tSC
  }
 set parseFl = ##class(ITFCOMMON.parseXmlFile).%New()
 set tSC = parseFl.ParseFile(tExportClsFilename, tItemName)

 if ( ($$$ISOK(tSC)) && (parseFl.IsItfExportFile()) )
  {

	 if (parseFl.itemsInfo.Count() < 2)
	 {
		  Write !, "File does not have config for any class in file" _ compNm
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for any class in file " _ compNm)
	 }
	 if (parseFl.itemsInfo.Count() '= clsList.Count())
	 {
		 set tSC =  $$$ERROR($$$GeneralError, "Number of classes in DB and classfile do not match")
		 Quit
	 }
	 if (parseFl.itemsInfo.GetAt(1).itemName = tItemName)
	 {

	 	FOR ind=2:1:parseFl.itemsInfo.Count()
	 	{
		 	set clsNm = parseFl.itemsInfo.GetAt(ind).itemName
		 	if clsList.Find($ZCVT(clsNm, "U"))
		 	{
	   			set tSC = ..CompareClassInternalWithSrcCtrl(clsNm,nmSp,
	   	 				passwd, env, parseFl.itemsInfo.GetAt(ind).versionNum)
	 			if $$$ISERR(tSC)
	 			{
		 			Quit
	 			}
		 	}
		 	else
		 	{
			 	set tSC =  $$$ERROR($$$GeneralError, "Could not find class name being deployed " _ clsNm)
			 	Quit
		 	}
	 	}
	 }
	 else
	 {
		 Write !, "File does not have config for " _ tItemName
  		 Quit $$$ERROR($$$GeneralError, "File does not have config for " _ tItemName)
	 }
  }
  Quit tSC

  set tSC = $$$OK
  NEW $NAMESPACE
  set $NAMESPACE = "ITFCOMMON"
   &sql(Select ID INTO :envId from ITFCOMMON_SrcCtrl.Environment where Name = :env)
      IF (SQLCODE '= 0) {
	      set tSC = $$$ERROR($$$GeneralError, "Could not get Env Id for " _ env)
		  Quit 
      }

  &sql(Declare C2 Cursor for  select  ClassName, ClassExportFile, ClassExportFileVersion
      INTO  :clsNm, :clsfile, :version
      from  ITFCOMMON_SrcCtrl.ClassItem 
      where  ClassName =  :clsName 
      and Environment = :envId and ClassExportFileVersion = :revNum)
  Set SQLCODE=0  
  &sql(OPEN C2) 
  For { 
	    &sql(FETCH C2)  

	    if (SQLCODE '= 0)
	    {
	       Quit
	    }
	    Write !, clsNm _ ", " _ clsfile _ ", " _ version
	    set extNm = ##class(ITFCOMMON.ItfSrcCtrlUtil).ExternalName(clsNm)
	    Write !, extNm

		set cmd = "svn update  -N --no-auth-cache --non-interactive --revision " _ version _ " --username " _ $username _ " --password " _ passwd _ " " _extNm
		Set stat = $ZF(-1, cmd)
		Write !, "cmd: " _cmd _ ": " _ stat
		if (stat = 0)
		{
		     // Export internal code
		     set tempFile = ##class(%Library.File).TempFilename()
		     if $F(clsNm, "CLS") >  $L(clsNm)
			 {
				set item = clsNm
	 		 }
	 		 else
	 		 {
				set item = clsNm _ "." _ "CLS"
	 		 }
			 Do ..exportFile(tempFile, item, nmSp)
			 if (  ##class(%File).Exists(tempFile))
			 {
			     	set tempFile2 = ##class(%Library.File).TempFilename()
			     	set cmd = "diff -w -B --suppress-common-lines " _ extNm _ " " _ tempFile _ " > " _ tempFile2
			   		Set stat = $ZF(-1, cmd)
			      	Write !, cmd _ " Stat: " _ stat
			   	    if (##class(%File).Exists(tempFile2))
			   	    {
				   	    if ##class(%File).GetFileSize(tempFile2) > 0
			   			{
				   			set tSC = $$$ERROR($$$GeneralError, "Src Control File is not current for " _ item)
				   			Quit
			   			}
         				Do ##class(%Library.File).Delete(tempFile2)
         				Do ##class(%Library.File).Delete(tempFile)
			   	    }
			   	    else
			   	    {
				   	    set tSC = $$$ERROR($$$GeneralError, "diff failed for " _ item)
				   	    Quit 
			   	    }
			 }
			 else
			 {
			     	set tSC = $$$ERROR($$$GeneralError, " Export failed: " _ item )
			     	Quit
			 }
		}
		else
		{
		   set tSC = $$$ERROR($$$GeneralError, "Unable to run svn update command for: " _ extNm)
		   Quit
		}
	}

	if $$$ISOK(tSC)
	{
		Write !, " SVN file content matches internal code " _ clsName
	}
	&sql(CLOSE C2)


  QUIT tSC

	set tSC = $$$OK
	if (rev '= "")
	{
		Do ##class(%File).Delete(fileNm)
		Set cmd= $$$SVNUPDATE _ " --revision " _ rev
		Set cmd= cmd _ " --username " _ $username _ " --password " _ passwd _ " " _  fileNm 

		Set status = $ZF(-1, cmd)
		if (status '= 0)
		{
			set tSC = $$$ERROR($$$GeneralError, $$$SVNUPDATE _ " --revision " _ rev _ " failed")
		}
		if ##class(%File).Exists(fileNm)
		{
			Write !, "Checked out " _ fileNm _ ", version: " _ rev
		}
		else {
  			Write !, "Could not find file " _ fileNm
  			set tSC = $$$ERROR($$$GeneralError, "Could not find file " _ fileNm)
 		}
	}
	else
	{		
		  set tSC = $$$ERROR($$$GeneralError, "Checkout: Revision number is required") 
	}

 	Quit tSC
